// Clip a tilted beaker against a horizontal liquid surface, preserving its illustrated fill area.
function polygonClip(poly,angle,level){const s=Math.sin(angle),c=Math.cos(angle),out=[];for(let i=0;i<poly.length;i++){const a=poly[i],b=poly[(i+1)%poly.length],da=a[0]*s+a[1]*c-level,db=b[0]*s+b[1]*c-level;if(da>=0)out.push(a);if((da>=0)!==(db>=0)){const f=da/(da-db);out.push([a[0]+f*(b[0]-a[0]),a[1]+f*(b[1]-a[1])]);}}return out;}
function area(poly){return Math.abs(poly.reduce((n,p,i)=>{const q=poly[(i+1)%poly.length];return n+p[0]*q[1]-q[0]*p[1];},0))/2;}
