 q('l3-calorimeter')?.classList.toggle('is-unplaced',!placed);set('l3VesselWater','d',water>0?`M-76 ${level}Q0 ${level+wave} 76 ${level}V88H-76Z`:'');set('l3MixingWave','d',water>0&&wave?`M-68 ${level+3}Q-30 ${level+wave*3} 0 ${level+3}T68 ${level+3}`:'');
